import { arrayUnion, doc, getDoc, updateDoc } from 'firebase/firestore';
import { Header } from './Header';
import { auth, db } from "../../firebase";
import CreateAppo from '../functions/createAppo';
import ProfileData from '../functions/registration-login/profileData';
import '../styles-of-components/profileData.css';
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

export const Home = () => {
  const [userDetails, setUserDetails] = useState(null);
  const navigatePages = useNavigate()
  const trapUserData = async (user) => {
    if (user) {
      const docRefUser = doc(db, "Users", user.uid);
      const dataUser = await getDoc(docRefUser);
      if (dataUser.exists()) {
        const userData = dataUser.data();
        setUserDetails(userData);
      }
    } else {
      setUserDetails(null);
    }
  };

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      trapUserData(user);
    });

    // Cleanup function
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (userDetails !== null) {
      console.log('userDetails: ', userDetails);
    }
  }, [userDetails]); // Este efecto se ejecuta cada vez que userDetails cambia.

  return (
    <div>
      <Header />
      <div className="userInfo">
        <ProfileData AppoText="Create First appointment" />
      </div>

    <div className="container_form">
      {userDetails !== null ? (
        userDetails.statusUser === "firstTime" ? (
          <>
            <CreateAppo AppoText={["Create first appointment", 'changeToUser']}/>
          </>
        ):(
          <>
          <div className="alertforfast" style={{width: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', marginTop: '25px'}}>
            <p>Do you wanna create appointments more faster?</p>
            <button onClick={()=> navigatePages('appointments')}>User Personal Area</button>
          </div>
          </>
        )
      ):(
        <p>loading...</p>
      )}

    </div>
    </div>
  )
}