import { arrayUnion, doc, getDoc, updateDoc } from 'firebase/firestore';
import { auth, db } from '../../firebase';
import { useEffect, useState } from 'react';
import AppointmentCalendar from '../functions/Calendarappo'
import Calendar from 'react-calendar';
import '../styles-of-components/createAppoin.css'

const CreateAppo = ({AppoText}) => {
  const [userDetails, setUserDetails] = useState(null)
  const [idAppoFDelete, setIDAppoFDelete] = useState('')
  const [dateSelected, setDateSelected] = useState({
    day: '',
    idAvAppo: '',
    time: []
  });
  const [currentUser, setCurrentUser] = useState(null);
  const [getDataAppo, setDataAppo] = useState({
    userNameAppo: "",
    userEmailAppo: "",
    takenOrNext: 'next',
    userService: "",
    timeAppo: dateSelected.time,
    dateAppo: dateSelected.day,
    isCurrUser: currentUser,
    userImage: '',
  });

  const changeStatusUser = async (IDuserStatus) => {
    try {
      // Obtén la referencia del documento específico del usuario
      const docRef = doc(db, "Users", IDuserStatus);
      const userData = await getDoc(docRef);  // Obtén el documento del usuario
      
      if (userData.exists()) {
        console.log(userData.data());  // Imprime los datos del usuario
        
        // Verifica el estado actual del usuario
        const currentStatus = userData.data().statusUser;
  
        // Si el estado actual es 'firstTime', lo cambiamos a 'currentUser'
        if (currentStatus === 'firstTime') {
          await updateDoc(docRef, { statusUser: 'currentUser' });
          console.log("El estado del usuario ha sido cambiado a currentUser.");
        } else {
          // Si el estado no es 'firstTime', lo cambiamos a 'firstTime' (por ejemplo, para la creación inicial)
          await updateDoc(docRef, { statusUser: 'firstTime' });
          console.log("El estado del usuario ha sido cambiado a firstTime.");
        }
        
      } else {
        console.log("No existe un usuario con ese ID.");
      }
    } catch (error) {
      console.error("Error al actualizar el estado del usuario:", error);
    }
  };
  
  
  const trapUserData = async (user) => {
    if (user) {
      const docRefUser = doc(db, "Users", user.uid);
      const dataUser = await getDoc(docRefUser);
      if (dataUser.exists()) {
        const userData = dataUser.data();
        setUserDetails(userData);
        setDataAppo((prevData) => ({
          ...prevData,
          userImage: userData.userPhoto, // Assuming userPhoto is the field name for the user's image
        }));
      }
    } else {
      setUserDetails(null);
    }
  };

  const setDataInArr = (e) => {
    setDataAppo({...getDataAppo, [e.target.name]: e.target.value });
  };
  
  const deleteAvAppo = async (idAppo, dayAppo) => {
    try {
      // Access the document in Firestore
      const docRefUser = doc(db, "appointmentsAviab", "HBQ3y5dNflCX3vKNZJZv");
      const docSnapshot = await getDoc(docRefUser);
  
      if (docSnapshot.exists()) {
        const data = docSnapshot.data();
        console.log("Document data:", data); // Log the document data to verify structure
  
        const appointmentsArray = data[dayAppo];
        if (!Array.isArray(appointmentsArray)) {
          console.log('here' + dayAppo)
          console.error("appointmentsArray is not an array");
          return false;
        }
  
        console.log("Original Appointments Array:", appointmentsArray); // Log before update
  
        // Update the specific appointment
        const updatedAppointments = appointmentsArray.map((appo) =>
          appo.idAvAppo === idAppo ? { ...appo, statusT: false } : appo
        );
        console.log("Updated Appointments Array:", updatedAppointments);
  
        // Update the Firestore document with the changes
        await updateDoc(docRefUser, {
          [dayAppo]: updatedAppointments, // Use square brackets for dynamic field name
        });
        return true;
      } else {
        console.error("Document does not exist.");
        return false;
      }
    } catch (error) {
      console.error("Error deleting appointment:", error);
      return false;
    }
  };
  
  
  
  

  /* Function for create a appointment */
  
  const createAppointment = async () => {
    const user = auth.currentUser; // Obtén el usuario autenticado directamente
    if (!user) {
      console.error("No hay usuario autenticado.");
      return;
    }
  
    const userDocRef = doc(db, "Users", user.uid);
  
    try {
      // Verifica si dateSelected está definido
      if (!dateSelected) {
        console.error("dateSelected is undefined or null");
        return;
      }
  
      const updatedDataAppo = {
        ...getDataAppo,
        timeAppo: dateSelected.time,
        dateAppo: dateSelected.day,
        isCurrUser: currentUser,
      };
  
      // Actualiza el documento del usuario con la nueva cita
      await updateDoc(userDocRef, {
        userAppointments: arrayUnion(updatedDataAppo),
      });
  
      console.log('Cita creada para el día: ' + dateSelected.day);
  
      // Elimina la cita disponible usando `deleteAvAppo`
      const isDeleted = await deleteAvAppo(dateSelected.idAvAppo, dateSelected.day);
      
      // Verifica si debe cambiarse el estado del usuario
      if (AppoText[1] === 'changeToUser') {
        await changeStatusUser(user.uid); // Asegúrate de esperar que el estado se cambie correctamente
      }
  
      // Si se eliminó correctamente la cita disponible, recarga la página
      if (isDeleted) {
        window.location.reload();
      } else {
        console.error("Failed to delete the available appointment.");
      }
    } catch (error) {
      console.error("Error adding appointment: ", error);
    }
  };
  
  



  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      trapUserData(user);
    });

    // Cleanup function
    return () => unsubscribe();
  }, []);

  /* Part CALENDARY */
  /* THIS IS THE PART OF THE CALENDARY */
  /* DO NOT PASS THROUGHT THIS PART WITHOUT READ THIS COMMENTS */

  const [date, setDate] = useState(new Date());  // Initialize date first
  const [dayCalendary, setDayCalendary] = useState(date.toDateString());
  const [listOfAppointments, setListOfAppointments] = useState([]);


  const tileClassName = ({ date, view }) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0); // Normalize today's date (remove time)

    if (view === "month" && date < today) {
      return "past-day"; // For past days
    }

    if (view === "month" && date.getTime() === today.getTime()) {
      return "current-day"; // For the current day
    }
  };

  const disablePastDates = ({ date }) => {
    const today = new Date();
    return date < today.setHours(0, 0, 0, 0); // Disables dates before today
  };

  
  /* Function to update date and dayCalendary */
  const handleDateChange = async (newDate) => {
    setDate(newDate);
    const formattedDate = newDate.toDateString(); // Format the new date for the dayCalendary
  
    setDayCalendary(formattedDate); // Update state with formatted date
  
    // Use formattedDate directly here to avoid using outdated state
    const docRefUser = doc(db, "appointmentsAviab", 'HBQ3y5dNflCX3vKNZJZv');
    const dataAppointments = await getDoc(docRefUser);
    if (dataAppointments.exists()) {
      const appointmentsForDay = dataAppointments.data()[formattedDate]; // Use formattedDate
      if(appointmentsForDay) {
        setListOfAppointments(appointmentsForDay);
      }else {
        console.log('There`re no appointments for this day');
        setListOfAppointments([]);

      }


    } else {
      console.log("No such document!");
    }
  };


    return (
        <>

          {userDetails !== null ? ( 
          <>
          <div className="createAppoForm">
          <h1>{[AppoText[0]]}</h1>
            <input type="text" name="userNameAppo" placeholder='Name' onChange={setDataInArr}/>
            <input type="text" name='userEmailAppo' placeholder='Email' onChange={setDataInArr}/>
            <input type="number" name="userNumberAppo" id="user_number" placeholder='Number' onChange={setDataInArr}/>
            <select id="pet-select" name='userService' onChange={setDataInArr}>
              <option value="">-- Select a service --</option>
              <option value="Laser Hair Removal">Laser Hair Removal</option>
              <option value="Microneedling">Microneedling</option>
              <option value="Laser Skin Resurfacing">Laser Skin Resurfacing</option>
              <option value="Body Contouring">Body Contouring</option>
              <option value="Hydrafacial">Hydrafacial</option>
            </select>
              <div className="calendar-container">
              <Calendar onChange={handleDateChange} value={date} tileClassName={tileClassName} tileDisabled={disablePastDates} />
              <p>Fecha seleccionada: {dayCalendary}</p>
            </div>
            <div className="aviableTimes">
  {listOfAppointments.map((ele) => {
    return (
      <div className="appoTimeDiv" key={ele.idAvAppo}>
        <p>{ele.day}</p> 
        <p>Time: {`${ele.time[0]} - ${ele.time[1]}`}</p>
        <p>Status: {ele.statusT ? 'Aviable' : 'No Aviable'}</p>
        <button
          style={{ background: ele.statusT ? "#007bff" : "#b9b9b9", cursor: ele.statusT ? "pointer" : 'not-allowed'}} 
          onClick={() => {
            if (ele.statusT) {

             setDateSelected({ day: ele.day, time: ele.time, idAvAppo: ele.idAvAppo });

              // Update getDataAppo to include the appointment ID (appoID)
              setDataAppo((prevDataAppo) => ({
                ...prevDataAppo,
               timeAppo: ele.time,
               dateAppo: ele.day,
                AppoID: ele.idAvAppo, // Adding appoID to the object
           }));
    }
  }}>Book</button>

      </div>
    );
  })}
</div>   
          </div>
          </>
          ) : (
            <div className="registerPlease">
              <p>Yo, u can register rq</p>
            </div>
          )}

        {dateSelected.day !== "" && dateSelected.time !== "" ? (
          <>
          <div className="containerlolxddddd">
            <div className="dateSelecterxdlol">
            <p>Your date selected: </p>
            <p>{dateSelected.day}</p>
            <p>{`${dateSelected.time[0]} - ${dateSelected.time[1]}`}</p>
            </div>
          </div>
          </>
        ) : (
          <></>
        )}
      <div className="payBeforeCreateAppo">
      </div>
    <div className="sendAppo">
      <button onClick={createAppointment}>Send</button>
    </div>
        </>

    );
};
export default CreateAppo