import React, { useEffect, useState } from "react";
import { Calendar, momentLocalizer } from "react-big-calendar";
import moment from "moment";
import "react-big-calendar/lib/css/react-big-calendar.css";
import '../../styles-of-components/adminStyle.css'
import { auth, db } from "../../../firebase";
import { doc, getDoc } from "firebase/firestore";

export const CalendaryAppos = () => {
  const [allUsers, setAllUsers] = useState([]);
  const [userDetails, setUserDetails] = useState(null);
  const [events, setEvents] = useState([]); // Estado inicial como array vacío

  // Función para obtener los detalles del usuario
  const trapUserData = async (user) => {
    if (user) {
      const docRefUser = doc(db, "Users", user.uid);
      const dataUser = await getDoc(docRefUser);
      if (dataUser.exists()) {
        setUserDetails(dataUser.data());
      }
    } else {
      setUserDetails(null);
    }
  };

  const localizer = momentLocalizer(moment);

  // useEffect para manejar la actualización de eventos cuando userDetails cambie
  useEffect(() => {
    if (userDetails && userDetails.userAppointments) {
      const formattedEvents = userDetails.userAppointments.map((el) => ({
        title: el.userNameAppo,
        start: new Date(`${el.dateAppo} ${el.timeAppo[0]}`),
        end: new Date(`${el.dateAppo} ${el.timeAppo[1]}`),  // Puedes ajustar si tienes una fecha final diferente
        allDay: false // Cambia esto según necesites
      }));

      setEvents(formattedEvents); // Actualizamos el estado de eventos
    }
  }, [userDetails]); // Se actualiza cuando userDetails cambie

  // Escuchar cambios en la autenticación del usuario
  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      trapUserData(user);
    });

    // Cleanup function
    return () => unsubscribe();
  }, []);

  return (
    <div style={{ height: 500 }}>
      <Calendar
        localizer={localizer}
        events={events} // Se pasan los eventos al calendario
        startAccessor="start"
        endAccessor="end"
        style={{ height: 500 }}
      />
    </div>
  );
};
