import { useState } from "react";
import { Header } from "../../../components/app/Header";
import { collection, doc, getDoc, getDocs, updateDoc } from "firebase/firestore";
import { auth, db } from "../../../firebase";
import { useNavigate } from "react-router-dom";
import { useEffect } from "react";
import { CalendaryAppos } from './calendarAdmin.'

export const UxAdmin = () => {
    const navigateLog = useNavigate();
    const [allUsers, setAllUsers] = useState([]);
    const [userDetails, setUserDetails] = useState(null);
    const [refresh, setRefresh] = useState('')
    const getAllData = async () => {
      const querySnapshot = await getDocs(collection(db, "Users"));
      const users = [];
      querySnapshot.forEach((doc) => {
        users.push(doc.data());
      });
      setAllUsers(users);
    };
    const [calOruser, setCalOrUser] = useState("userInfo")
  
    const trapUserData = async (user) => {
      if (user) {
        const docRefUser = doc(db, "Users", user.uid);
        const dataUser = await getDoc(docRefUser);
        if (dataUser.exists()) {
          setUserDetails(dataUser.data());
        }
      } else {
        setUserDetails(null);
      }
    };
  
    const logOutF = async () => {
      try {
        await auth.signOut();
        setUserDetails(null);  // Limpia los datos del usuario
        setTimeout(() => {
          navigateLog("/logIn");  // Navega después de un pequeño delay
        }, 100);  // 100ms de retraso
      } catch (e) {
        console.log(e);
      }
    };

    const deleteAvAppo = async (idAppo, dayAppo) => {
      try {
        // Access the document in Firestore
        const docRefUser = doc(db, "appointmentsAviab", "HBQ3y5dNflCX3vKNZJZv");
        const docSnapshot = await getDoc(docRefUser);
    
        if (docSnapshot.exists()) {
          const data = docSnapshot.data();
          console.log("Document data:", data); // Log the document data to verify structure
    
          const appointmentsArray = data[dayAppo];
          if (!Array.isArray(appointmentsArray)) {
            console.log('here' + dayAppo)
            console.error("appointmentsArray is not an array");
            return false;
          }
    
          console.log("Original Appointments Array:", appointmentsArray); // Log before update
    
          // Update the specific appointment
          const updatedAppointments = appointmentsArray.map((appo) =>
            appo.idAvAppo === idAppo ? { ...appo, statusT: true } : appo
          );
          console.log("Updated Appointments Array:", updatedAppointments);
    
          // Update the Firestore document with the changes
          await updateDoc(docRefUser, {
            [dayAppo]: updatedAppointments, // Use square brackets for dynamic field name
          });
          return true;
        } else {
          console.error("Document does not exist.");
          return false;
        }
      } catch (error) {
        console.error("Error deleting appointment:", error);
        return false;
      }
    };


    const findEditApptakenOrNext = async (appoID) => {
      try {
        // Itera por todos los usuarios
        const querySnapshot = await getDocs(collection(db, "Users"));
        for (const userDoc of querySnapshot.docs) {
          const userData = userDoc.data();
    
          // Verifica si tiene citas (userAppointments)
          if (userData.userAppointments) {
            const appointmentIndex = userData.userAppointments.findIndex(
              (appointment) => appointment.appoID === appoID
            );
    
            // Si encuentra la cita, actualiza el campo takenOrNext
            if (appointmentIndex !== -1) {
              const updatedAppointments = [...userData.userAppointments];
              updatedAppointments[appointmentIndex].takenOrNext = "taken";
    
              // Actualiza la base de datos con las nuevas citas
              await updateDoc(doc(db, "Users", userDoc.id), {
                userAppointments: updatedAppointments,
              });
              console.log(`Cita con ID ${appoID} actualizada exitosamente ${refresh}`);
              return;
            }
          }
        }
    
        console.log(`No se encontró ninguna cita con ID ${appoID}`);
      } catch (error) {
        console.error("Error al actualizar la cita:", error);
      }
    };
    const deleteAnAppo = async (appoID) => {
      try {
        const querySnapshot = await getDocs(collection(db, "Users"));
        const updatedUsers = [];  // New array to store updated users
    
        for (const userDoc of querySnapshot.docs) {
          const userData = userDoc.data();
          let updatedAppointments = userData.userAppointments;
    
          if (userData.userAppointments) {
            const appointmentIndex = userData.userAppointments.findIndex(
              (appointment) => appointment.appoID === appoID
            );
    
            if (appointmentIndex !== -1) {
              updatedAppointments = [...userData.userAppointments];
              updatedAppointments.splice(appointmentIndex, 1);
    
              // Update the Firestore document with the updated appointments
              await updateDoc(doc(db, "Users", userDoc.id), {
                userAppointments: updatedAppointments,
              });
    
              console.log("Cita eliminada correctamente");
            }
          }
    
          // Push updated user data to new array (even if appointments are not changed)
          updatedUsers.push({
            ...userData,
            userAppointments: updatedAppointments,
          });
          setRefresh('Delete an apo');
        }
    
        // Update state with the new user data to refresh the UI
        setAllUsers(updatedUsers);
      } catch (error) {
        console.error("Error al eliminar la cita:", error);
      }
    };


    
    const deleteAllApo = (idAppo, dateAppo, AppoIDForAppo) => {
      console.log('This is the ID:' + idAppo + '--- this is the date:' + dateAppo);
        deleteAnAppo(idAppo);
        deleteAvAppo(AppoIDForAppo, dateAppo);
    };
    

    
    useEffect(() => {
      const unsubscribe = auth.onAuthStateChanged((user) => {
        trapUserData(user);
      });
  
      // Cleanup function
      return () => unsubscribe();
    }, []);
  
    useEffect(() => {
      getAllData()
    },[])
  
    return (
      <>
        <Header />
        <div className="containerAdminInfo">
          <div className="containerInfoAdmin">
            {userDetails ? (
              <>
                <img src={userDetails.userPhoto} alt="User" />
                <h2>{userDetails.userName}</h2>
                <p>{userDetails.userEmail}</p>
                <div 
                style={{ width: "150px", height: "50px", background: "red" }}
                onClick={logOutF}>Sign Out</div>
                <div 
                style={{ width: "150px", height: "50px", background: "#fddf" , marginTop: "15px" }}
                onClick={()=>setCalOrUser()}
                >Show calendary</div>
                <div 
                style={{ width: "150px", height: "50px", background: "#fddf" , marginTop: "15px" }}
                onClick={()=>setCalOrUser('userInfo')}
                >Show User Panel</div>
              </>
            ) : (
              <>
                <p>Wanna log in / Sign up?</p>
                <div
                  style={{ width: "150px", height: "50px", background: "red" }}
                  onClick={() => navigateLog("/login")}>
                  Log in / Sign Up
                </div>
              </>
            )}
          </div>
            <div className="allUserAppoiments">
              {(userDetails && allUsers && calOruser === 'userInfo')? (
              <>
                {allUsers.filter((el) => el.userAppointments && el.userAppointments.length !== 0).map((ex)=> {
                  return (
                    <div className="usersId" key={ex.userID}>
                      <h3>{ex.userName}</h3>
                      <p>{ex.userEmail}</p> 
                      <p>{ex.userNumber}</p>
                      {ex.userAppointments.map((el) => (
                        <div className="userAppoInfo"  key={el.appoID}>
                          <img src={el.userImage} alt="User" />
                          <p>{el.userNameAppo}</p>
                          <p>{el.userEmailAppo}</p>
                          <p>{el.userService}</p>
                          <p>{el.userNumberAppo}</p>
                          <p>{el.dataForAppo}</p>
                          <p>{el.timeForAppo}</p>
                          <p>Status Appointment: {el.takenOrNext}</p>
                          <div className="buttonOfCancellAppo" onClick={() => findEditApptakenOrNext(el.appoID)}>Complete Appo</div>
                          <div className="buttonDeleteAppo" onClick={() => deleteAllApo(el.appoID, el.dateAppo, el.AppoID)}>
                            Delete Appo
                          </div>

                        </div>
                      ))}
                    </div>
                  );
                })}
              </>
              ):(
                <div>
                <CalendaryAppos/>
              </div>
              )}
            </div>
        </div>
      </>
    );
}
